 public string SourceText="",DeskName,DisplayTitle;public bool OutputScale;public int AuxSend=-1;public string NameText{get{return string.IsNullOrEmpty(DeskName)?(DisplayTitle??("Input "+Number)):DeskName;}}
 readonly Button muteButton=new Button(),soloButton=new Button(),sendButton=new Button(),preButton=new Button();readonly Panel sendPanel=new Panel();
 public event Action<int,bool> MuteEdited,SoloEdited,SendEdited,PreEdited;
