 void InstallMixerButtons(){foreach(var b in new Button[]{muteButton,soloButton,sendButton,preButton}){b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderColor=Color.FromArgb(83,100,116);b.BackColor=Color.FromArgb(38,47,58);b.ForeColor=Color.FromArgb(225,233,243);b.Font=new Font("Segoe UI",8);b.Enabled=false;}muteButton.Text="M";muteButton.AccessibleName="Mute channel";soloButton.Text="S";soloButton.AccessibleName="Solo channel";Controls.Add(muteButton);Controls.Add(soloButton);Controls.Add(sendPanel);sendPanel.Controls.Add(sendButton);sendPanel.Controls.Add(preButton);sendPanel.Visible=false;muteButton.Click+=delegate{if(onState.HasValue&&MuteEdited!=null)MuteEdited(Number,onState==1);};soloButton.Click+=delegate{if(soloState.HasValue&&SoloEdited!=null)SoloEdited(Number,soloState!=1);};sendButton.Click+=delegate{if(sendState.HasValue&&SendEdited!=null)SendEdited(Number,sendState!=1);};preButton.Click+=delegate{if(preState.HasValue&&PreEdited!=null)PreEdited(Number,preState!=1);};PlaceMixerButtons();}
 void PlaceMixerButtons(){int w=Math.Max(20,(Width-12)/2);muteButton.Bounds=new Rectangle(4,Height-29,w,25);soloButton.Bounds=new Rectangle(8+w,Height-29,w,25);if(IsStereoMaster)muteButton.Bounds=new Rectangle(4,Height-29,Math.Max(40,Width-8),25);sendPanel.Bounds=new Rectangle(4,61,Math.Max(46,Width-8),52);sendButton.Bounds=new Rectangle(0,0,sendPanel.Width,24);preButton.Bounds=new Rectangle(0,27,sendPanel.Width,24);}
 public void ApplyMixer(MixerChannelState s,int aux){SourceText=s.Id<96?InputSources.Label(s.Source,false):s.Id<104?"Bus mix":s.Id<116?"Aux mix":s.Id<124?"Matrix mix":"Stereo mix";onState=s.On;soloState=s.Solo;sendState=s.SendOn;preState=s.Pre;DeskName=s.Name;DisplayTitle=MixerParameter.Title(s.Id);OutputScale=s.Id>=96;AuxSend=s.Id<96?aux:-1;PanSlider.Visible=s.Id<96&&aux<0;sendPanel.Visible=AuxSend>=0;muteButton.Enabled=s.On.HasValue;soloButton.Enabled=s.Solo.HasValue;soloButton.Visible=s.Id<124;muteButton.BackColor=s.On==0?Color.FromArgb(158,55,64):Color.FromArgb(38,47,58);soloButton.BackColor=s.Solo==1?Color.FromArgb(142,103,32):Color.FromArgb(38,47,58);sendButton.Enabled=s.SendOn.HasValue;sendButton.Text=s.SendOn==1?"Send ON":s.SendOn==0?"Send OFF":"Send ?";preButton.Enabled=s.Pre.HasValue;preButton.Text=s.Pre==1?"PRE":s.Pre==0?"POST":"Pre/Post ?";PlaceMixerButtons();}
 string DisplayLevel{get{return MixerParameter.LevelLabel(OutputScale?124:0,DisplayRaw);}}
