sealed partial class Studio {
 static void TestExpandedUi(){string path=System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"layout.ini"),prior=System.IO.File.Exists(path)?System.IO.File.ReadAllText(path):null;try{using(var app=new Studio())using(var report=new System.IO.StreamWriter(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"expanded-ui.txt"))){app.Show();for(int view=0;view<7;view++){app.banks.SelectedIndex=view;Application.DoEvents();int[] ids=FaderConnection.ViewIds(view);if(app.strips.Controls.Count!=ids.Length)throw new Exception("Output bank count wrong");for(int i=0;i<ids.Length;i++)if(((ChannelStrip)app.strips.Controls[i]).Number!=ids[i]+1)throw new Exception("Output controls target wrong channels");report.WriteLine("View "+view+" targets verified");}app.banks.SelectedIndex=0;app.Connect();DateTime end=DateTime.UtcNow.AddSeconds(11);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(10);}foreach(string mode in new string[]{"main","aux","outputs"}){if(mode=="aux")app.auxMix.SelectedIndex=1;if(mode=="outputs")app.banks.SelectedIndex=4;end=DateTime.UtcNow.AddSeconds(mode=="main"?0:5);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(10);}using(var image=new Bitmap(app.Width,app.Height)){app.DrawToBitmap(image,new Rectangle(Point.Empty,app.Size));image.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"mixer-"+mode+".png"));}}report.WriteLine("PASS: main mix, aux sends, output banks and stereo master rendered with live data.");app.Close();}}finally{if(prior!=null)System.IO.File.WriteAllText(path,prior);}}
 ComboBox auxMix=new ComboBox();Label soloBadge=new Label(),mixBanner=new Label();TextBox channelName=new TextBox(),shortChannelName=new TextBox();TableLayoutPanel mixSurface=new TableLayoutPanel();Panel masterHost=new Panel();CheckBox showMaster=new CheckBox();Button saveName=new Button();FlowLayoutPanel masterPanel=new FlowLayoutPanel();int priorNameChannel=-1;bool nameDirty;string pendingName,pendingShort;DateTime nameSent;
 int SelectedAux{get{return banks.SelectedIndex<4?auxMix.SelectedIndex-1:-1;}}
 int SelectedId{get{return channel-1;}}
 void InstallMixerUi(){banks.Items.AddRange(new object[]{"Buses 1–8","Aux masters 1–12","Matrix 1–4 L/R"});auxMix.Width=140;Style(auxMix);auxMix.Items.Add("Main mix");for(int i=1;i<=12;i++)auxMix.Items.Add("Aux "+i+" sends");auxMix.SelectedIndex=0;toolbar.Controls.Add(auxMix);soloBadge.AutoSize=true;soloBadge.Padding=new Padding(8,5,8,0);soloBadge.ForeColor=Color.FromArgb(240,197,96);toolbar.Controls.Add(soloBadge);mixBanner.AutoSize=true;mixBanner.Padding=new Padding(8,5,8,0);toolbar.Controls.Add(mixBanner);
 var namePanel=new Panel{Width=228,Height=88,Margin=new Padding(0,0,12,5)};var names=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=3,Margin=Padding.Empty};names.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,75));names.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,25));names.RowStyles.Add(new RowStyle(SizeType.Absolute,18));names.RowStyles.Add(new RowStyle(SizeType.Absolute,26));names.RowStyles.Add(new RowStyle(SizeType.Absolute,28));channelName.Dock=shortChannelName.Dock=DockStyle.Fill;channelName.MaxLength=16;shortChannelName.MaxLength=4;channelName.BackColor=shortChannelName.BackColor=Color.FromArgb(38,47,58);channelName.ForeColor=shortChannelName.ForeColor=ForeColor;names.Controls.Add(new Label{Text="Long name",Dock=DockStyle.Fill},0,0);names.Controls.Add(new Label{Text="Short",Dock=DockStyle.Fill},1,0);names.Controls.Add(channelName,0,1);names.Controls.Add(shortChannelName,1,1);saveName.Text="Save name";Style(saveName);saveName.Dock=DockStyle.Fill;names.Controls.Add(saveName,0,2);names.SetColumnSpan(saveName,2);namePanel.Controls.Add(names);info.Controls.Add(namePanel);info.Controls.SetChildIndex(namePanel,1);shortChannelName.TextChanged+=delegate{if(shortChannelName.Focused)nameDirty=true;};channelName.TextChanged+=delegate{if(channelName.Focused)nameDirty=true;};saveName.Click+=delegate{try{if(midi==null)throw new InvalidOperationException("Connect first.");midi.Rename(SelectedId,channelName.Text,shortChannelName.Text);pendingName=channelName.Text;pendingShort=shortChannelName.Text;nameSent=DateTime.UtcNow;nameDirty=true;state.Text="Name sent to "+MixerParameter.Title(SelectedId);}catch(Exception e){state.Text=e.Message;}};
 var masterTitle=new Label{Text="STEREO MASTER",Height=24,Width=228,ForeColor=Color.FromArgb(160,177,193)};masterTitle.Dock=DockStyle.Top;masterHost.Controls.Add(masterTitle);masterPanel.Dock=DockStyle.Fill;masterPanel.Width=176;masterPanel.Height=340;masterPanel.WrapContents=false;masterPanel.Margin=new Padding(0,0,12,5);InstallStereoMaster();masterHost.Controls.Add(masterPanel);masterHost.Controls.SetChildIndex(masterTitle,1);masterPanel.SizeChanged+=delegate{foreach(Control c in masterPanel.Controls){c.Size=new Size(Math.Max(58,masterPanel.ClientSize.Width-6),Math.Max(264,masterPanel.ClientSize.Height-8));}};mixSurface.ColumnCount=2;mixSurface.RowCount=1;mixSurface.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));mixSurface.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,132));mixSurface.RowStyles.Add(new RowStyle(SizeType.Percent,100));mixSurface.Controls.Add(strips,0,0);mixSurface.Controls.Add(masterHost,1,0);masterHost.Dock=DockStyle.Fill;mixSurface.Dock=DockStyle.Fill;showMaster.Text="Stereo master";showMaster.AutoSize=true;showMaster.Checked=true;toolbar.Controls.Add(showMaster);showMaster.CheckedChanged+=delegate{masterHost.Visible=showMaster.Checked;mixSurface.ColumnStyles[1].Width=showMaster.Checked?132:0;SaveLayout();};auxMix.SelectedIndexChanged+=delegate{ChangeMixerView();};}
 void ChangeMixerView(){if(banks.SelectedIndex<0)return;auxMix.Enabled=banks.SelectedIndex<4;if(banks.SelectedIndex>=4&&auxMix.SelectedIndex!=0)auxMix.SelectedIndex=0;if(midi!=null)midi.SetMixerView(banks.SelectedIndex,SelectedAux);int[] ids=FaderConnection.ViewIds(banks.SelectedIndex);if(Array.IndexOf(ids,SelectedId)<0)channel=ids[0]+1;DrawChannels();}
 ChannelStrip MakeStrip(int id){var s=new ChannelStrip(id+1){DisplayTitle=MixerParameter.Title(id),OutputScale=id>=96};s.ApplyMixer(new MixerChannelState{Id=id},SelectedAux);s.Pick+=delegate(int n){channel=n;if(stereoMaster!=null){stereoMaster.Selected=false;stereoMaster.Invalidate();}foreach(ChannelStrip strip in strips.Controls){strip.Selected=strip.Number==n;strip.Invalidate();}Details();};s.FaderChanged+=delegate(int n,int raw){try{if(midi==null)throw new InvalidOperationException("Connect first.");midi.SetLevel(n-1,raw);}catch(Exception e){s.RejectEdit();state.Text=e.Message;}};s.PanChanged+=delegate(int n,int value){try{if(midi==null)throw new InvalidOperationException("Connect first.");midi.WritePan(n-1,value);}catch(Exception e){s.PanSlider.Reject();state.Text=e.Message;}};s.MuteEdited+=delegate(int n,bool value){Act(delegate{midi.SetMute(n-1,value);});};s.SoloEdited+=delegate(int n,bool value){Act(delegate{midi.SetSolo(n-1,value);});};s.SendEdited+=delegate(int n,bool value){Act(delegate{midi.SetSendOn(n-1,value);});};s.PreEdited+=delegate(int n,bool value){Act(delegate{midi.SetSendPre(n-1,value);});};return s;}
 void Act(Action action){try{if(midi==null)throw new InvalidOperationException("Connect first.");action();}catch(Exception e){state.Text=e.Message;}}
 void DrawMixerChannels(){strips.SuspendLayout();while(strips.Controls.Count>0)strips.Controls[0].Dispose();foreach(int id in FaderConnection.ViewIds(banks.SelectedIndex)){var s=MakeStrip(id);s.Selected=SelectedId==id;strips.Controls.Add(s);}strips.ResumeLayout();if(midi!=null)RefreshMixer();Details();}
 void UpdateMixerStrip(ChannelStrip strip){var data=midi.Channel(strip.Number-1);strip.RefreshEdit();strip.Raw=data.Level;strip.Meter=data.Meter;strip.PanSlider.SetConfirmed(data.Pan);strip.MeterPoint=MeterProtocol.PointLabel(strip.Number<=96?inputPoint:outputPoint);strip.ApplyMixer(data,SelectedAux);strip.Invalidate();}
 void RefreshMixer(){foreach(ChannelStrip strip in strips.Controls)UpdateMixerStrip(strip);UpdateStereoMaster();int? solo=midi.SoloStatus;soloBadge.ForeColor=solo==1?Color.FromArgb(240,197,96):Color.FromArgb(160,177,193);soloBadge.Text=solo==1?"SOLO ACTIVE":solo==0?"Solo off":"Solo status loading";mixBanner.ForeColor=SelectedAux>=0?Color.FromArgb(114,207,235):ForeColor;mixBanner.Text=SelectedAux<0?(banks.SelectedIndex<4?"MAIN MIX":banks.SelectedIndex==4?"BUS OUTPUTS":banks.SelectedIndex==5?"AUX MASTERS":"MATRIX MASTERS"):"AUX "+(SelectedAux+1)+" SENDS · "+(midi.AuxModeValue==1?"FIXED":midi.AuxModeValue==0?"VARIABLE":"Loading mode");}
 void RenderMixerDetails(){if(midi==null){channelName.Enabled=shortChannelName.Enabled=saveName.Enabled=false;return;}var data=midi.Channel(SelectedId);RefreshInspectorCard(data);if(pendingName!=null&&((data.Name==pendingName&&data.ShortName==pendingShort)||(DateTime.UtcNow-nameSent).TotalSeconds>3)){pendingName=pendingShort=null;nameDirty=false;}string sourceText=SelectedId<96?InputSources.Label(data.Source,true):SelectedId<104?"Internal bus mix":SelectedId<116?"Internal aux mix":SelectedId<124?"Internal matrix mix":"Stereo mix";if(SelectedId<96&&data.Source>=25&&data.Source<=120)sourceText+="\r\n"+midi.Card((data.Source.Value-25)/16).SourceDetail;if(sourceValue.Text!=sourceText)sourceValue.Text=sourceText;channelTitle.Text=SelectedId>=124?"Stereo master":MixerParameter.Title(SelectedId);faderValue.Text=MixerParameter.LevelLabel(SelectedId,SelectedId>=124?stereoMaster.Raw:data.Level);signalValue.Text=data.Meter.HasValue?MeterProtocol.LevelLabel(data.Meter.Value):"Unknown";inspectorPanField.Visible=SelectedId<96&&SelectedAux<0;if(priorNameChannel!=SelectedId){priorNameChannel=SelectedId;nameDirty=false;pendingName=pendingShort=null;channelName.Text=data.Name??"";shortChannelName.Text=data.ShortName??"";}else if(!nameDirty){if(channelName.Text!=(data.Name??""))channelName.Text=data.Name??"";if(shortChannelName.Text!=(data.ShortName??""))shortChannelName.Text=data.ShortName??"";}channelName.Enabled=shortChannelName.Enabled=data.NameComplete;saveName.Enabled=data.NameComplete;}
 void ResetMixer(){cardField.Visible=false;editingCardSlot=-1;editingCardSignature=null;cardLabelDirty=false;soloBadge.Text="Solo status unknown";ResetStereoMaster();foreach(ChannelStrip s in strips.Controls)s.ApplyMixer(new MixerChannelState{Id=s.Number-1},SelectedAux);channelName.Enabled=shortChannelName.Enabled=saveName.Enabled=false;}
